            body=json.load(r); status=r.status
    except urllib.error.HTTPError as e:
        body=e.read().decode(); status=e.code
    print(status, name, body)
time.sleep(2)
ls=listing()
for name,p in plan.items():
    ok = name in ls and ls[name]==sha(p)
    print("VERIFIED" if ok else "NOT-YET", name)
    if ok:
        p.unlink()
print("remaining files:")
for p in sorted(root.rglob("*")):
